package com.fasterxml.jackson.databind.jsontype.impl;

import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.BeanProperty;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.deser.std.NullifyingDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeIdResolver;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class TypeDeserializerBase__deserializeWithNativeTypeId_TriageGen2Test {

    private TestableTypeDeserializer sut;
    private JsonParser mockParser;
    private DeserializationContext mockContext;
    private JavaType mockBaseType;
    private JsonDeserializer<Object> mockDeserializer;
    private Object expectedResult;

    // Concrete implementation to allow testing protected method and overriding internal lookups
    private static class TestableTypeDeserializer extends TypeDeserializerBase {
        private JsonDeserializer<Object> forcedDeserializer;
        private JsonDeserializer<Object> defaultImplDeserializer;
        private boolean throwOnFindDeserializer = false;

        protected TestableTypeDeserializer(JavaType baseType, TypeIdResolver idRes, String typePropertyName, boolean typeIdVisible, JavaType defaultImpl) {
            super(baseType, idRes, typePropertyName, typeIdVisible, defaultImpl);
        }

        @Override
        public TypeDeserializer forProperty(com.fasterxml.jackson.databind.BeanProperty prop) {
            return null;
        }

        @Override
        public com.fasterxml.jackson.annotation.JsonTypeInfo.As getTypeInclusion() {
            return null;
        }

        @Override
        protected JsonDeserializer<Object> _findDeserializer(DeserializationContext ctxt, String typeId) throws IOException {
            if (throwOnFindDeserializer) throw new IOException("Find error");
            return forcedDeserializer;
        }

        @Override
        protected JsonDeserializer<Object> _findDefaultImplDeserializer(DeserializationContext ctxt) throws IOException {
            return defaultImplDeserializer;
        }

        public void setForcedDeserializer(JsonDeserializer<Object> deser) {
            this.forcedDeserializer = deser;
        }

        public void setDefaultImplDeserializer(JsonDeserializer<Object> deser) {
            this.defaultImplDeserializer = deser;
        }

        public void setThrowOnFindDeserializer(boolean val) {
            this.throwOnFindDeserializer = val;
        }
    }

    @Before
    public void setUp() {
        mockParser = mock(JsonParser.class);
        mockContext = mock(DeserializationContext.class);
        mockBaseType = mock(JavaType.class);
        mockDeserializer = mock(JsonDeserializer.class);
        expectedResult = new Object();

        sut = new TestableTypeDeserializer(mockBaseType, mock(com.fasterxml.jackson.databind.jsontype.TypeIdResolver.class), "type", true, null);
    }

    @Test
    public void testDeserializeWithNullTypeId_AndDefaultDeserializerFound() throws IOException {
        sut.setDefaultImplDeserializer(mockDeserializer);
        when(mockDeserializer.deserialize(mockParser, mockContext)).thenReturn(expectedResult);

        Object result = sut._deserializeWithNativeTypeId(mockParser, mockContext, null);

        assertSame(expectedResult, result);
        verify(mockDeserializer).deserialize(mockParser, mockContext);
    }

    @Test
    public void testDeserializeWithNullTypeId_AndNoDefaultDeserializer() throws IOException {
        sut.setDefaultImplDeserializer(null);
        when(mockContext.reportInputMismatch(eq(mockBaseType), any(String.class))).thenReturn("error_msg");

        Object result = sut._deserializeWithNativeTypeId(mockParser, mockContext, null);

        assertEquals("error_msg", result);
        verify(mockContext).reportInputMismatch(eq(mockBaseType), contains("No (native) type id found"));
    }

    @Test
    public void testDeserializeWithStringTypeId() throws IOException {
        String typeId = "testId";
        sut.setForcedDeserializer(mockDeserializer);
        when(mockDeserializer.deserialize(mockParser, mockContext)).thenReturn(expectedResult);

        Object result = sut._deserializeWithNativeTypeId(mockParser, mockContext, typeId);

        assertSame(expectedResult, result);
        verify(mockDeserializer).deserialize(mockParser, mockContext);
    }

    @Test
    public void testDeserializeWithNonStringTypeId() throws IOException {
        Integer typeId = 123;
        sut.setForcedDeserializer(mockDeserializer);
        when(mockDeserializer.deserialize(mockParser, mockContext)).thenReturn(expectedResult);

        Object result = sut._deserializeWithNativeTypeId(mockParser, mockContext, typeId);

        assertSame(expectedResult, result);
        // Verifies that String.valueOf(typeId) was used (implicitly via the mock interaction)
        verify(mockDeserializer).deserialize(mockParser, mockContext);
    }

    @Test(expected = IOException.class)
    public void testDeserializeWithTypeId_ThrowsException() throws IOException {
        sut.setThrowOnFindDeserializer(true);
        sut._deserializeWithNativeTypeId(mockParser, mockContext, "someId");
    }

    @Test(expected = IOException.class)
    public void testDeserializeWithTypeId_DeserializationThrowsException() throws IOException {
        sut.setForcedDeserializer(mockDeserializer);
        when(mockDeserializer.deserialize(any(), any())).thenThrow(new IOException("deser fail"));

        sut._deserializeWithNativeTypeId(mockParser, mockContext, "someId");
    }
}
